# Generated by scripts/build-native-motion.py; review provenance in config/motion-native-v1.json.
"""Poster-only /3 identity of the frozen R2 phase authority (ed9f232c).

The execution module is fixed in code. Legacy /1 and queue lifecycle are not
modified. This controller never claims/finishes jobs, selects a JSON module,
weakens a source digest or treats a changed approval as the same approval.
"""
from __future__ import annotations

from backlot import motion_native_runtime as native

from copy import deepcopy
from datetime import datetime, timezone
import json
from pathlib import Path
import re
import shutil
import uuid

from backlot.motion_public_io_v1 import WorkError, atomic_private, fingerprint, read_json, sha

ROOT = Path(__file__).resolve().parents[1]
CONTRACT = 'haike.motion-public-poster-production/3'
KIND = 'studio_investment_recompose'
REQUEST_FILE = 'motion-public-poster-v3-request.json'
BINDINGS_FILE = 'motion-public-poster-v3-bindings.json'
RESULT_FILE = 'phase-result-poster-v3.json'
DECISIONS = {'approve', 'reject', 'changes_requested'}
ENGINES = {'observed-controls/3'}
PACK_KEY = 'observed-poster'
REFERENCE_ID = 'vibrant-poster'


def require(condition, message):
    if not condition:
        raise WorkError(message)


def _execution():
    # Deliberately no fallback to /1 and no caller-selected module.
    from backlot import motion_native_public_poster_execution_v3
    return motion_public_poster_execution_v3


def preflight(value):
    require(isinstance(value, dict) and value.get('engine') in ENGINES
            and value.get('pack_key') == PACK_KEY and value.get('reference_id') == REFERENCE_ID,
            '只接受observed-controls/3的observed-poster/vibrant-poster固定海报路线')
    return _execution().preflight(value)


def runtime():
    return {'execution': _execution().runtime(), 'transport': {
        'abi': 'haike.motion-public-poster-parent/3', 'controller_sha256': sha(Path(__file__)),
        'prepare_cli_sha256': sha(ROOT/'scripts/motion_public_poster_production_v3.py'),
        'helpers': {name: sha(ROOT/name) for name in [
            'backlot/motion_public_io_v1.py', 'lib/checkpoint.py', 'backlot/work_catalog.py']}}}


def _base(request):
    return {k: v for k, v in request.items() if k not in {'phase', 'review_binding'}}


def _preview_request(queue, request):
    source = request.get('render_revision')
    if source is None:
        return _base(request)
    require(isinstance(source, dict) and isinstance(source.get('project_id'), str)
            and re.fullmatch(r'studio-[0-9a-f]{16}', source['project_id']), 'render修订源身份无效')
    original = read_json(queue.projects_root/source['project_id']/'artifacts'/REQUEST_FILE)
    require(not original.get('render_revision') and original.get('request_sha256') == source.get('request_sha256')
            and original.get('render_id') == source.get('render_id'), 'render修订的原preview身份改变')
    _identity(queue, original)
    return original


def _identity(queue, request):
    require(isinstance(request, dict), '冻结请求须为对象')
    base = _base(request)
    core = {k: v for k, v in base.items() if k not in {'request_sha256', 'render_id'}}
    require(base.get('contract') == CONTRACT and fingerprint(core) == base.get('request_sha256'),
            '公开海报组件/3冻结身份改变')
    require(isinstance(base.get('project_id'), str) and re.fullmatch(r'studio-[0-9a-f]{16}', base['project_id'])
            and base.get('render_id') == 'motion-public-poster-v3-'+base['request_sha256'][:20], '项目或输出身份无效')
    require(base.get('input_engine') in ENGINES and base.get('pack_key') == PACK_KEY
            and base.get('reference', {}).get('template_id') == REFERENCE_ID, '未登记的poster执行路线')
    project = queue.projects_root/base['project_id']
    require(project.resolve().is_relative_to(queue.projects_root.resolve()) and not project.is_symlink(), '项目路径越界')
    record = project/'artifacts'/REQUEST_FILE
    require(record.is_file() and not record.is_symlink() and read_json(record) == base, '冻结项目记录改变')
    return project


def _locations(queue, request):
    project = _identity(queue, request)
    path = project/'artifacts'/BINDINGS_FILE
    require(path.is_file() and not path.is_symlink(), '本地位置映射缺失或为链接')
    bindings = read_json(path)
    work = Path(bindings['work_root'])
    require(work.is_absolute() and not work.is_symlink()
            and work.resolve().is_relative_to((ROOT.parent/'.local').resolve()), '作业缓存映射越界')
    original = _preview_request(queue, request)
    folder = work/original['render_id']
    require(not folder.is_symlink() and folder.resolve().is_relative_to(work.resolve()), '阶段目录越界')
    return project, folder, bindings


def prepare(queue, value):
    n = preflight(value)
    require(n.get('input_engine') in ENGINES and value.get('pack_key') == PACK_KEY
            and n.get('reference', {}).get('template_id') == REFERENCE_ID, '执行层返回未登记poster路线')
    sources = {**n['paths'], 'script.json': n['script'], 'asr.json': n['asr']}
    require(all(isinstance(name, str) and re.fullmatch(r'[A-Za-z0-9][A-Za-z0-9_.-]{0,99}', name)
                and Path(path).is_file() and not Path(path).is_symlink() for name, path in sources.items()), '源资产名或文件无效')
    work = Path(value.get('work_root', ROOT.parent/'.local/motion-public-poster-work-v3')).resolve()
    require(work.is_relative_to((ROOT.parent/'.local').resolve()) and not work.is_symlink(), '作业缓存须在本副本忽略目录内')
    core = {'contract': CONTRACT, 'title': value['title'], 'pack_key': value['pack_key'], 'spec': n['spec'],
            'input_engine': n['input_engine'], 'reference': n['reference'], 'original_package_equivalence': False,
            'source_receipts': deepcopy(value.get('source_receipts', {})),
            'external_fonts': deepcopy(value.get('external_fonts', {})),
            'transcription_corrections': deepcopy(value.get('caption_corrections', [])),
            'environment': n['environment'], 'runtime': runtime(), 'duration': n['duration'], 'frames': n['frames'],
            'origins': {name: {'sha256': sha(path)} for name, path in sources.items()}, 'publication': False, 'paid_calls': 0}
    core['project_id'] = 'studio-'+fingerprint(core)[:16]
    digest = fingerprint(core)
    request = {**core, 'request_sha256': digest, 'render_id': 'motion-public-poster-v3-'+digest[:20]}
    from lib.checkpoint import init_project
    project = queue.projects_root/request['project_id']
    record = project/'artifacts'/REQUEST_FILE
    if not record.exists():
        require(not project.exists(), '项目已有未完成现场，保留并明确恢复，不自动覆盖')
        init_project(request['project_id'], title=request['title'], pipeline_type='animated-explainer', pipeline_dir=queue.projects_root)
        destination = project/'assets/motion-public'; destination.mkdir(parents=True)
        for name, path in sources.items():
            shutil.copy2(path, destination/name)
        atomic_private(project/'artifacts'/BINDINGS_FILE, {
            'tool_root': str(Path(value['tool_root']).resolve()), 'dependency_root': str(Path(value['dependency_root']).resolve()),
            'ffmpeg_root': str(Path(value['ffmpeg_root']).resolve()) if value.get('ffmpeg_root') else None,
            'work_root': str(work), 'origin_locators': {name: str(Path(path).resolve()) for name, path in sources.items()}})
        atomic_private(record, request)
    validate(queue, request)
    return request


def validate(queue, request, *, execution=True):
    project, folder, bindings = _locations(queue, request)
    if request.get('render_revision'):
        validate(queue, _preview_request(queue, request), execution=execution)
    origins = request.get('origins')
    require(isinstance(origins, dict) and origins, '冻结素材清单缺失')
    for name, row in origins.items():
        require(isinstance(name, str) and re.fullmatch(r'[A-Za-z0-9][A-Za-z0-9_.-]{0,99}', name), '冻结素材路径无效')
        path = project/'assets/motion-public'/name
        require(path.is_file() and not path.is_symlink() and sha(path) == row.get('sha256'), '冻结素材缺失或改变：'+name)
    if execution:
        require(runtime() == request['runtime'], '执行或阶段控制器字节改变；保留旧实现，不豁免SHA')
        _, identities = _execution().environment(bindings['tool_root'], bindings['dependency_root'], bindings.get('ffmpeg_root'),
                                                engine=request['input_engine'])
        require(identities == request['environment'], '工具或实际依赖字节改变')
        if request.get('phase') == 'render':
            _preview_parent(queue, request)
            require(request.get('review_binding') == _review_binding(folder, request), '冻结的具体批准已失效')
    return project, folder


def _preview_binding(folder, request):
    path = folder/'preview.json'
    require(path.is_file() and not path.is_symlink(), '实际预览回执缺失或为链接')
    receipt = read_json(path); images = receipt.get('images')
    preview_request_sha = request.get('render_revision', {}).get('request_sha256', request['request_sha256'])
    require(receipt.get('request_sha256') == preview_request_sha and isinstance(images, list) and images,
            '本期完整预览身份或图片清单无效')
    names = [row.get('name') if isinstance(row, dict) else None for row in images]
    require(all(isinstance(name, str) and re.fullmatch(r'[A-Za-z0-9][A-Za-z0-9_.-]*\.png', name) for name in names)
            and len(names) == len({name.casefold() for name in names}), '实际预览PNG名字无效或重复')
    from PIL import Image
    for row in images:
        image = folder/'preview'/row['name']
        require(image.is_file() and not image.is_symlink() and not image.parent.is_symlink()
                and sha(image) == row.get('sha256'), '实际预览PNG缺失或改变：'+row['name'])
        with Image.open(image) as decoded:
            require(decoded.format == 'PNG', '实际预览文件不是PNG')
            decoded.verify()
    return {'request_sha256': preview_request_sha, 'preview_sha256': sha(path), 'images': deepcopy(images)}


def _review_binding(folder, request):
    binding = _preview_binding(folder, request)
    path = folder/'visual-review.json'
    require(path.is_file() and not path.is_symlink(), '须先明确审核本期完整实际预览')
    approval = read_json(path)
    require(approval.get('decision') == 'approve', '当前决定为拒绝、要求修改或未批准，不能导出')
    require(approval.get('binding') == binding and approval.get('preview_sha256') == binding['preview_sha256']
            and approval.get('inspected_images') == binding['images']
            and isinstance(approval.get('reviewer'), str) and approval['reviewer'].strip()
            and isinstance(approval.get('approval_id'), str) and re.fullmatch(r'[0-9a-f]{32}', approval['approval_id']),
            '当前具体批准或实际图片绑定失效')
    concrete = {**binding, 'decision': 'approve', 'approval_id': approval['approval_id'], 'approval_sha256': sha(path)}
    if request.get('render_revision'):
        require(concrete == request['render_revision'].get('approval_binding'), 'render修订冻结的具体批准已改变')
    return concrete


def _phase_jobs(queue, request, phase):
    # Read every matching parent, without the public list's limit.
    with queue._connection() as connection:
        rows = connection.execute('SELECT job_id,frozen_request FROM production_jobs WHERE project_id=? AND kind=? AND parent_job_id=?',
                                  (request['project_id'], KIND, request['render_id'])).fetchall()
    jobs = []
    for row in rows:
        frozen = json.loads(row['frozen_request'])
        if frozen.get('contract') == CONTRACT and frozen.get('phase') == phase:
            require(_base(frozen) == _base(request), '同阶段原父绑定不同冻结内容，保留并核对')
            jobs.append(queue.get(row['job_id'], include_private=True))
    require(len(jobs) <= 1, '同一阶段存在多个原父，禁止自动选择或新增')
    return jobs


def _preview_parent(queue, request):
    original = _preview_request(queue, request)
    jobs = _phase_jobs(queue, original, 'preview')
    require(jobs and jobs[0]['status'] == 'completed' and not jobs[0]['cancel_requested'], '原preview父未完成或已取消/未知')
    require(jobs[0]['frozen_request'] == {**original, 'phase': 'preview'}, '原preview父完整冻结身份不符')
    # The completed parent's original result is the full-preview witness.
    # A newly shortened local receipt, even reapproved, cannot replace it.
    _, folder, _ = _locations(queue, request)
    binding = _preview_binding(folder, request)
    require(binding == jobs[0].get('result'), '当前回执或图片清单不等于原preview父保存的原始完整预览')
    return binding


def review(queue, request, evidence):
    _, folder = validate(queue, _base(request))
    require(isinstance(evidence, dict) and evidence.get('decision') in DECISIONS,
            '审核决定须明确选择approve、reject或changes_requested')
    _preview_parent(queue, request)
    binding = _preview_binding(folder, request)
    require(evidence.get('preview_sha256') == binding['preview_sha256'] and evidence.get('inspected_images') == binding['images']
            and isinstance(evidence.get('reviewer'), str) and evidence['reviewer'].strip(), '审核须绑定全部实际预览PNG及审核者')
    approval = {'decision': evidence['decision'], 'binding': binding, 'preview_sha256': binding['preview_sha256'],
                'inspected_images': binding['images'], 'approval_id': uuid.uuid4().hex, 'reviewer': evidence['reviewer'].strip(),
                'note': deepcopy(evidence.get('note', '')), 'continuous_watching': 'pending',
                'continuous_listening': 'pending', 'device_listening': 'pending'}
    atomic_private(folder/'visual-review.json', approval)
    return {'reviewed': True, 'decision': approval['decision'], 'approved': approval['decision'] == 'approve',
            'approval_id': approval['approval_id'], 'scope': 'sampled-preview'}


def _output_binding(project, folder, request, expected_review=None):
    path = folder/RESULT_FILE; done = read_json(path)
    execution_receipt = folder/'result.json'; output = folder/'motion-public.mp4'
    require(all(p.is_file() and not p.is_symlink() for p in [path, execution_receipt, output]), '完整成片或阶段质量回执缺失')
    quality = read_json(execution_receipt)
    require(done.get('request_sha256') == request['request_sha256'] and done.get('execution_result_sha256') == sha(execution_receipt)
            and quality.get('full_decode') == 'passed' and quality.get('output_sha256') == sha(output) == done.get('output_sha256'),
            '成片或质量回执身份改变')
    binding = done.get('review_binding')
    preview_request_sha = request.get('render_revision', {}).get('request_sha256', request['request_sha256'])
    require(isinstance(binding, dict) and binding.get('request_sha256') == preview_request_sha
            and binding.get('decision') == 'approve' and binding.get('approval_sha256')
            and (expected_review is None or binding == expected_review), '成片具体批准绑定改变')
    managed = project/'renders'/request['render_id']/'motion-public.mp4'
    require(managed.is_file() and not managed.is_symlink() and sha(managed) == done['output_sha256'], '托管成片缺失或改变')
    return {'output_path': str(managed), 'output_sha256': done['output_sha256'],
            'execution_result_sha256': done['execution_result_sha256'], 'review_binding': binding}


def health(queue, request):
    """Historical queue status is not rewritten by current artifact availability."""
    result = {'request_sha256': request.get('request_sha256')}
    try:
        project, folder = validate(queue, _base(request), execution=False)
        result['frozen_inputs'] = {'status': 'valid'}
    except Exception as exc:
        return {**result, 'frozen_inputs': {'status': 'invalid', 'reason': str(exc)}, 'execution': {'status': 'blocked'},
                'preview': {'status': 'unchecked'}, 'review': {'status': 'unchecked'}, 'output': {'status': 'unchecked'}}
    try:
        validate(queue, _base(request)); result['execution'] = {'status': 'ready'}
    except Exception as exc:
        result['execution'] = {'status': 'blocked', 'reason': str(exc)}
    for name, check, marker in [('preview', lambda: _preview_parent(queue, request), folder/'preview.json'),
                                 ('output', lambda: _output_binding(project, folder, request), folder/RESULT_FILE)]:
        try:
            result[name] = {'status': 'valid', **check()}
        except Exception as exc:
            present = marker.exists() or (folder/'preview').exists() if name == 'preview' else any(
                (folder/file).exists() for file in [RESULT_FILE, 'result.json', 'motion-public.mp4'])
            result[name] = {'status': 'invalid' if present else 'missing', 'reason': str(exc)}
    try:
        _preview_parent(queue, request)
        result['review'] = {'status': 'approved', **_review_binding(folder, request)}
    except Exception as exc:
        try:
            decision = read_json(folder/'visual-review.json').get('decision')
        except (ValueError, OSError, AttributeError):
            decision = None
        result['review'] = {'status': 'not_approved', 'decision': decision, 'reason': str(exc)}
    return result


def submit(queue, request, *, phase='preview'):
    _identity(queue, request)
    require(phase in {'preview', 'render'}, '制作阶段无效')
    if phase == 'preview' and request.get('render_revision'):
        original = _preview_request(queue, request)
        _preview_parent(queue, request)
        return {**queue.get(_phase_jobs(queue, original, 'preview')[0]['job_id']), 'availability': health(queue, request)}
    existing = _phase_jobs(queue, request, phase)
    if existing and (phase == 'preview' or existing[0]['status'] not in {'paused', 'failed'}):
        return {**queue.get(existing[0]['job_id']), 'availability': health(queue, request)}
    _, folder = validate(queue, _base(request))
    frozen = {**_base(request), 'phase': phase}
    if phase == 'render':
        _preview_parent(queue, request)
        frozen['review_binding'] = _review_binding(folder, request)
    if existing:
        require(existing[0]['frozen_request'] == frozen, '原父绑定另一份具体批准；保留原父，须明确新revision')
        job = queue.get(existing[0]['job_id'])
    else:
        job = queue.submit(kind=KIND, project_id=request['project_id'], source='codex', priority='normal',
                           parent_job_id=request['render_id'], frozen_request=frozen, start_paused=True,
                           idempotency_key=CONTRACT+':'+request['request_sha256']+':'+phase)
    require(queue.get(job['job_id'], include_private=True)['frozen_request'] == frozen, '幂等键已绑定不同具体冻结请求')
    _phase_jobs(queue, request, phase)
    return {**job, 'availability': health(queue, request)}


def new_render_revision(queue, request, *, reason):
    """Explicit local recovery: same original preview/PNG, new render identity.

    The original unclaimed render remains paused/attempt0 with its exact frozen
    approval. No preview is submitted/drawn, no provider or user prompt added.
    """
    require(isinstance(reason, str) and reason.strip(), 'render修订须记录明确原因')
    original = _preview_request(queue, request)
    project, folder = validate(queue, original)
    _preview_parent(queue, original)
    approval = _review_binding(folder, original)
    parents = _phase_jobs(queue, request, 'render')
    require(parents and parents[0]['status'] == 'paused' and parents[0]['attempt_count'] == 0
            and not parents[0]['cancel_requested'], '仅允许显式修订从未领取的暂停render，保留其他状态现场')
    require(not any((folder/name).exists() for name in ['render-started-poster-v3.json', RESULT_FILE, 'result.json', 'motion-public.mp4']),
            '已有render现场，不能以批准变更修订覆盖')
    core = {k: deepcopy(v) for k, v in original.items() if k not in {'project_id', 'request_sha256', 'render_id'}}
    core['render_revision'] = {'project_id': original['project_id'], 'request_sha256': original['request_sha256'],
        'render_id': original['render_id'], 'previous_job_id': parents[0]['job_id'], 'reason': reason.strip(),
        'approval_binding': approval,
        'revision_id': fingerprint({'previous_job_id': parents[0]['job_id'], 'approval': approval, 'reason': reason.strip()})}
    core['project_id'] = 'studio-'+fingerprint(core)[:16]
    digest = fingerprint(core)
    revised = {**core, 'request_sha256': digest, 'render_id': 'motion-public-poster-v3-'+digest[:20]}
    target = queue.projects_root/revised['project_id']
    if target.exists():
        require(read_json(target/'artifacts'/REQUEST_FILE) == revised, 'render修订现场不完整或不同，保留并核对')
        validate(queue, revised)
        return revised
    from lib.checkpoint import init_project
    init_project(revised['project_id'], title=revised['title'], pipeline_type='animated-explainer', pipeline_dir=queue.projects_root)
    shutil.copytree(project/'assets/motion-public', target/'assets/motion-public')
    atomic_private(target/'artifacts'/BINDINGS_FILE, read_json(project/'artifacts'/BINDINGS_FILE))
    atomic_private(target/'artifacts'/REQUEST_FILE, revised)
    validate(queue, revised)
    return revised


def validate_claim(queue, job_id):
    """Read only. Root must call this BEFORE claim_local_recompose."""
    job = queue.get(job_id, include_private=True); request = job.get('frozen_request') or {}
    require(job.get('kind') == KIND and request.get('contract') == CONTRACT
            and job.get('project_id') == request.get('project_id') and job.get('parent_job_id') == request.get('render_id'), '待领取父身份不符')
    require((job['status'] == 'paused' or job['status'] == 'failed' and job['retryable']) and not job['cancel_requested'],
            '原父状态不允许领取，保留原任务')
    require(request.get('phase') in {'preview', 'render'}, '制作阶段无效')
    validate(queue, request)
    jobs = _phase_jobs(queue, request, request['phase'])
    require(jobs and jobs[0]['job_id'] == job_id, '待领取父不是唯一原阶段父')
    if request['phase'] == 'render':
        _preview_parent(queue, request)
    return {'job_id': job_id, 'claim_ready': True, 'phase': request['phase'], 'request_sha256': request['request_sha256']}


def _claimed(queue, job, request):
    actual = queue.get(job['job_id'], include_private=True)
    require(actual['status'] == 'running' and actual['kind'] == KIND and actual['project_id'] == request['project_id']
            and actual['parent_job_id'] == request['render_id'] and actual['frozen_request'] == request
            and job.get('frozen_request') == request
            and all(job.get(key) == actual.get(key) for key in ['job_id', 'kind', 'project_id', 'parent_job_id', 'worker_id', 'attempt_count'])
            and isinstance(actual.get('worker_id'), str) and actual['worker_id'] and actual['attempt_count'] > 0,
            '真实running父/完整冻结/工作者/尝试次数与领取不符')
    try:
        deadline = datetime.fromisoformat(actual['lease_expires_at'].replace('Z', '+00:00'))
    except (AttributeError, TypeError, ValueError):
        deadline = None
    require(deadline and deadline.tzinfo is not None and deadline > datetime.now(timezone.utc), '原父领取租约已过期或无效')
    require(not actual['cancel_requested'], '原父已请求取消，保留现场')
    return actual


def _guard(queue, job, request):
    _claimed(queue, job, request)
    project, folder = validate(queue, request)
    jobs = _phase_jobs(queue, request, request['phase'])
    require(jobs and jobs[0]['job_id'] == job['job_id'], '阶段父不唯一或身份改变')
    if request['phase'] == 'render':
        _preview_parent(queue, request)
    return project, folder


def _register(queue, job, request, project, folder, invocation, verified):
    from backlot.work_catalog import WorkCatalog
    probe = _execution()._ffprobe(invocation)
    catalog = WorkCatalog(queue.projects_root)
    _guard(queue, job, request)
    work = catalog.register(request['project_id'], Path(verified['output_path']), work_key='main', mode='manual',
        event_id=job['job_id'], quality_passed=False, actor=CONTRACT, title=request['title'], ffprobe=probe)
    _guard(queue, job, request)
    _output_binding(project, folder, request, request['review_binding'])
    return {'status': 'completed', 'stage': '公开海报组件/3整片已完成，连续听看待验',
            'result': {**verified, 'work_id': work['work_id'], 'qa_status': 'pending'}}


def run(queue, job):
    """A real claimed parent only; failures keep their original artifacts/ID."""
    try:
        request = job['frozen_request']
        require(request.get('phase') in {'preview', 'render'}, '制作阶段无效')
        project, folder = _guard(queue, job, request)
        folder.mkdir(parents=True, exist_ok=True)
        _, _, bindings = _locations(queue, request)
        execution_request = _preview_request(queue, request)
        execution_project = _identity(queue, execution_request)
        invocation = {**execution_request, 'phase': request['phase'], 'tool_root': bindings['tool_root'], 'dependency_root': bindings['dependency_root'],
                      'ffmpeg_root': bindings.get('ffmpeg_root')}
        # Live Python callback only, never stored in the frozen JSON. D calls
        # this around each actual media command, in addition to our step guards.
        invocation['_phase_guard'] = lambda: _guard(queue, job, request)
        if request['phase'] == 'render':
            invocation['review_binding'] = request['review_binding']
        if request['phase'] == 'preview' and (folder/'preview.json').exists():
            binding = _preview_parent(queue, request)
            _guard(queue, job, request)
            return {'status': 'completed', 'stage': '原实际预览已核对', 'result': binding}
        if request['phase'] == 'render' and (folder/RESULT_FILE).exists():
            output = _output_binding(project, folder, request, request['review_binding'])
            _guard(queue, job, request)
            return _register(queue, job, request, project, folder, invocation, output)
        marker = folder/(request['phase']+'-started-poster-v3.json')
        stale = ((folder/'preview').exists() if request['phase'] == 'preview' else
                 any((folder/name).exists() for name in ['motion-public.mp4', 'result.json']))
        require(not marker.exists() and not stale, '阶段有中断或损坏现场；保留原父，须明确恢复')
        atomic_private(marker, {'request_sha256': request['request_sha256'], 'phase': request['phase'], 'job_id': job['job_id']})
        _guard(queue, job, request)
        _execution().build_project(execution_project, folder, invocation)
        _guard(queue, job, request)
        result = _execution().render_project(execution_project, folder, invocation)
        _guard(queue, job, request)
        require(isinstance(result, dict) and result.get('status') == 'completed', '实际执行阶段未完成，保留现场')
        if request['phase'] == 'preview':
            binding = _preview_binding(folder, request)
            _guard(queue, job, request)
            return {'status': 'completed', 'stage': '本期实际预览已生成，待逐图明确审核', 'result': binding}
        output = folder/'motion-public.mp4'; quality = folder/'result.json'; produced = Path(result['result']['output_path'])
        require(produced.resolve() == output.resolve() and output.is_file() and not output.is_symlink()
                and sha(output) == result['result']['output_sha256'] and quality.is_file() and not quality.is_symlink(), '实际编码输出身份无效')
        quality_data = read_json(quality)
        require(quality_data.get('full_decode') == 'passed' and quality_data.get('output_sha256') == sha(output), '实际完整解码或输出质量身份无效')
        managed = project/'renders'/request['render_id']/'motion-public.mp4'
        require(not managed.parent.is_symlink() and managed.resolve().is_relative_to(project.resolve()), '托管输出路径越界')
        _guard(queue, job, request)
        managed.parent.mkdir(parents=True, exist_ok=True)
        if not managed.exists():
            shutil.copy2(output, managed)
        require(managed.is_file() and not managed.is_symlink() and sha(managed) == sha(output), '原托管输出改变，禁止覆盖')
        _guard(queue, job, request)
        atomic_private(folder/RESULT_FILE, {'request_sha256': request['request_sha256'], 'review_binding': request['review_binding'],
            'output_sha256': sha(output), 'execution_result_sha256': sha(quality), 'paid_calls': 0, 'publication': False})
        verified = _output_binding(project, folder, request, request['review_binding'])
        _guard(queue, job, request)
        return _register(queue, job, request, project, folder, invocation, verified)
    except Exception as exc:
        return {'status': 'failed', 'stage': '公开海报组件/3保留原父与现场，待明确恢复',
                'error': {'type': type(exc).__name__, 'message': str(exc)[:1000]}, 'retryable': False,
                'safe_resume_point': 'motion-public-poster-v3-explicit-recovery'}
